// DB and TOKEN_STORE come from Cloudflare.Env (generated by `wrangler types` into
// worker-configuration.d.ts from wrangler.jsonc's bindings) — only secrets/vars not
// declared in wrangler.jsonc need to be hand-listed here. Extending instead of
// redeclaring means the binding types can't silently drift from wrangler.jsonc.
export interface Env extends Cloudflare.Env {
  GOOGLE_CLIENT_ID: string;
  GOOGLE_CLIENT_SECRET: string;
  SESSION_SECRET: string;
  TOKEN_ENCRYPTION_KEY: string;
  PRIMARY_ACCOUNT_EMAIL: string;
}

export interface SessionData {
  userId: string;
  email: string;
  createdAt: number;
  expiresAt: number;
}

// Shared Hono generic — every router/middleware that touches bindings or the
// session variable should use this instead of redeclaring `{ Bindings: Env }`,
// so their types can't drift from each other or from src/index.ts.
export interface AppBindings {
  Bindings: Env;
  Variables: {
    session: SessionData;
  };
}
